sp_widget.css:
.tm-schedule-card {
    background: #fff;
    border-radius: 18px;
    padding: 24px;
    box-shadow: 0 4px 20px rgba(0,0,0,.08);
}

.card-header {
    margin-bottom: 20px;
}

.card-header h3 {
    margin: 0;
    font-size: 22px;
    font-weight: 700;
    color: #111827;
}

.card-header p {
    margin: 5px 0 0;
    color: #6b7280;
}

.tm-table {
    width: 100%;
}

.tm-table thead th {
    background: #f8fafc;
    color: #64748b;
    padding: 14px;
    text-transform: uppercase;
    font-size: 12px;
    font-weight: 600;
}

.tm-table td {
    padding: 16px;
    border-bottom: 1px solid #edf2f7;
    vertical-align: middle;
}

.tm-table tbody tr:hover {
    background: #f8fafc;
}

.patient-info {
    display: flex;
    align-items: center;
    gap: 12px;
}

.avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: #14b8a6;
    color: #fff;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
}

.patient-name {
    font-weight: 600;
}

.status-badge {
    padding: 7px 14px;
    border-radius: 20px;
    font-size: 12px;
    font-weight: 600;
    min-width: 90px;
    display: inline-block;
    text-align: center;
}

.scheduled {
    background: #dbeafe;
    color: #1d4ed8;
}

.taken {
    background: #dcfce7;
    color: #166534;
}

.nottaken {
    background: #fee2e2;
    color: #991b1b;
}

.text-success {
    color: #10b981;
    font-size: 20px;
}

.text-danger {
    color: #ef4444;
    font-size: 20px;
}

.empty-row {
    text-align: center;
    color: #64748b;
}

sp_widget.script:
(function() {

    data.schedules = [];
    data.total = 0;

    var start = gs.beginningOfToday();
    var end = gs.endOfToday();

    var gr = new GlideRecord('x_snc_trackmed_dose_log');

    // Show all records for admins
    if (!gs.hasRole('x_snc_trackmed.admin')) {
        gr.addQuery('care_taker', gs.getUserID());
    }

    gr.addQuery('work_start', '>=', start);
    gr.addQuery('work_start', '<=', end);

    gr.orderBy('work_start');
    gr.query();

    while (gr.next()) {

        var patientName = gr.patient.getDisplayValue() || '';

        data.schedules.push({
            patient: patientName,
            medication: gr.medication.getDisplayValue(),
            work_start: gr.work_start.getDisplayValue(),
            status: gr.status.getDisplayValue(),
            confirmed: gr.caregiver_confirmed == true,
            initials: patientName ? patientName.charAt(0).toUpperCase() : '',
            caregiver: gr.care_taker.getDisplayValue()
        });

        data.total++;
    }

})();
